rules:
@media (max-width: 760px) {
  .tool-rail { border-width: 1px; border-style: solid; border-image: none; bottom: calc(var(--status-h) + 6px); left: 6px; width: 54px; padding: 4px; border-color: var(--line-strong); border-radius: 7px; box-shadow: var(--shadow-sm); background: rgba(242, 242, 239, 0.98); top: calc(var(--topbar-h) + var(--contextual-h) + 8px); }
}

@keyframes popover-in { 
  0% { opacity: 0; transform: translateX(-6px) scale(0.98); }
  100% { opacity: 1; transform: none; }
}

@keyframes selection-in { 
  0% { opacity: 0; transform: translate(-50%, -7px); }
  100% { opacity: 1; transform: translate(-50%, 0px); }
}

@media (max-width: 760px) {
  :root { --topbar-h: 54px; --status-h: 0px; --inspector-w: 0px; }
  .mobile-only { display: grid !important; }
  .desktop-only { display: none !important; }
  .mobile-dock { display: flex; }
  .topbar { grid-template-columns: minmax(0px, 1fr) auto; height: var(--topbar-h); padding: 0px 8px 0px 7px; }
  .topbar-leading { min-width: 0px; }
  .brand strong, .brand .version, .top-divider, #pagesToggle { display: none; }
  .doc-title { width: min(47vw, 250px); padding: 0px 7px; font-size: var(--ui-type-xl); }
  .history-group { display: none; }
  .file-group { gap: 3px; }
  .file-group .primary-button span { display: none; }
  .file-group .icon-button { width: 36px; height: 36px; }
  .stage-wrap, .app:not(.inspector-open) .stage-wrap { top: var(--topbar-h); left: 0px; right: 0px; bottom: calc(72px + env(safe-area-inset-bottom)); }
  .canvas-vignette { box-shadow: none; }
  .quick-controls { left: 10px; top: 12px; width: 46px; padding: 6px 5px; border-radius: 16px; }
  .quick-slider { width: 35px; height: 112px; }
  .quick-slider input { height: 58px; }
  .quick-color { width: 34px; height: 34px; }
  .selection-bar { top: 10px; max-width: calc(100% - 78px); height: 42px; left: auto; right: 8px; transform: none; overflow-x: auto; padding: 4px; }
  @keyframes selection-in { 
  0% { opacity: 0; transform: translateY(-6px); }
  100% { opacity: 1; transform: none; }
}
  .selection-title { padding: 0px 7px; }
  .selection-bar button { min-width: 38px; padding: 0px 7px; }
  .selection-bar button span { display: none; }
  .wheel-toggle { display: none; }
  .empty-hint { width: 78%; top: 46%; }
  .hint-keys { display: none; }
  .empty-mark { width: 66px; height: 66px; }
  .mobile-dock { position: absolute; z-index: 82; left: 8px; right: 8px; bottom: calc(8px + env(safe-area-inset-bottom)); height: 58px; border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 18px; box-shadow: var(--shadow); padding: 5px 6px; align-items: stretch; justify-content: space-around; }
  .mobile-dock .tool-icon, .dock-action .tool-icon { width: 25px; height: 25px; display: grid; place-items: center; }
  .mobile-dock .tool-icon svg, .dock-action svg { width: 21px; height: 21px; }
  .mobile-dock .tool-label, .dock-action .tool-label { font-size: var(--ui-type-xs); font-weight: 700; }
  .inspector { position: absolute; z-index: 104; left: 8px; right: 8px; top: auto; bottom: calc(8px + env(safe-area-inset-bottom)); width: auto; min-width: 0px; max-width: none; height: min(72vh, 620px); border-radius: 22px; transform: translateY(calc(100% + 20px)); opacity: 0; pointer-events: none; }
  .app.inspector-open .inspector { transform: none; opacity: 1; pointer-events: auto; }
  .app.inspector-open .stage-wrap { right: 0px; }
  .inspector-head { height: 55px; }
  .inspector-tabs { height: 48px; }
  .inspector-section { padding: 13px 14px calc(14px + env(safe-area-inset-bottom)); }
  .panel-scrim { position: absolute; display: block; z-index: 101; inset: var(--topbar-h) 0 0; background: rgba(35, 33, 29, 0.25); backdrop-filter: blur(2px); }
  .mobile-tool-sheet { display: block; position: absolute; z-index: 108; left: 8px; right: 8px; bottom: calc(8px + env(safe-area-inset-bottom)); border-radius: 22px; padding: 7px 12px 15px; }
  .sheet-handle { width: 38px; height: 4px; background: rgb(200, 195, 186); border-radius: 3px; margin: 1px auto 7px; }
  .sheet-title { display: flex; justify-content: space-between; align-items: center; min-height: 46px; padding: 0px 3px; }
  .sheet-title > div { display: flex; flex-direction: column; gap: 2px; }
  .mobile-tool-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 7px; }
  .mobile-tool-grid .tool-button.active::before { display: none; }
  .pages-panel { z-index: 106; top: calc(var(--topbar-h) + 8px); left: 8px; right: 8px; bottom: calc(8px + env(safe-area-inset-bottom)); width: auto; border-radius: 20px; transform: translateY(calc(100% + 30px)); }
  .pages-panel.open { transform: none; }
  .floating-panel { z-index: 109; left: 8px; right: 8px; top: auto; bottom: calc(8px + env(safe-area-inset-bottom)); width: auto; border-radius: 20px; }
  .dialog { border-radius: 20px; }
  .toast { bottom: 84px; max-width: 85%; text-align: center; }
  .zoom-hud { bottom: 80px; }
}

@media (max-width: 760px) {
  .doc-title { width: 39vw; }
  #newBtn, #openBtn, #saveBtn { display: none; }
  #exportBtn { display: flex; }
  .file-group #settingsToggle { display: none; }
  .quick-controls { transform: scale(0.92); transform-origin: left top; }
  .mobile-tool-grid { grid-template-columns: repeat(4, 1fr); }
  .selection-title strong { display: none; }
  .selection-divider { display: none; }
}

@media (pointer: coarse) {
  button { min-height: 36px; }
  .tool-rail .tool-button { min-height: 48px; }
  .color-chip { width: 29px; height: 29px; }
  .control-row { min-height: 49px; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation: auto ease 0s 1 normal none running none !important; transition: none !important; }
}

@media (max-width: 760px) {
  .inspector, .pages-panel, .floating-panel, .mobile-tool-sheet { max-width: calc(100% - 16px); }
  .topbar { max-width: 100%; overflow: hidden; }
  .stage-wrap, .statusbar, .mobile-dock { max-width: 100%; }
}

@media (max-width: 760px) {
  .quiet-button { color: rgb(93, 90, 83); height: 28px; padding: 0px 8px; border-radius: 3px; font-size: var(--ui-type-lg); font-weight: 600; }
}

@media (max-width: 760px) {
  .quiet-button:hover { color: var(--ink); background: rgba(255, 255, 255, 0.78); box-shadow: inset 0 0 0 1px var(--line); }
}

@media (max-width: 760px) {
  .primary-button { background: var(--accent); min-height: 30px; height: 30px; padding: 0px 10px; border-radius: 4px; font-size: var(--ui-type-lg); font-weight: 650; box-shadow: rgba(31, 102, 94, 0.22) 0px 1px 2px; }
}

@media (max-width: 760px) {
  .tool-button.active { color: var(--accent); background: rgba(31, 102, 94, 0.12); box-shadow: rgba(31, 102, 94, 0.25) 0px 0px 0px 1px inset; }
}

@media (max-width: 760px) {
  .tool-button.active::before { content: ""; position: absolute; background: var(--accent); left: -4px; width: 2px; height: 18px; border-radius: 0px 1px 1px 0px; }
}

@media (max-width: 760px) {
  .tool-button.featured::after, .tool-button.emphasis::after { background: var(--accent-2); top: 5px; right: 5px; width: 3px; height: 3px; }
}

@media (max-width: 760px) {
  .layer-row.active { border-color: rgba(30, 98, 90, 0.35); background: var(--accent-faint); box-shadow: inset 2px 0 0 var(--accent); }
